const input = $input.first().json || {};
const requestId = input.request_id || input.requestId || '';
const toolInput = input.tool_input || input.toolInput || {};
const original = String(toolInput.text || toolInput.question || '').trim();
const clarifyQuestion = original
  ? `Anladığım kadarıyla: "${original}". Devam etmeden önce bütçe ve hedef tarih bilgisini paylaşır mısın?`
  : 'Devam edebilmem için lütfen hedefini, bütçeni ve zaman planını paylaşır mısın?';
return [{ json: { request_id: requestId, success: true, data: { summary: 'Clarify adımı üretildi.', clarify_question: clarifyQuestion, selected_tool: 'clarify' }, error: null, usage: { time_ms: 95, tokens: 45, cost: 0.00045 }, artifacts: [] } }];
